124→/// Context for variable resolution.
125→///
126→/// Variables are resolved in priority order:
127→/// 1. Prompt values from current run (highest priority)
128→/// 2. Saved preferences from previous runs
129→/// 3. User-defined variables from `vars:` config
130→/// 4. Environment variables
131→/// 5. Built-in variables (lowest priority)
132→#[derive(Debug, Default)]
133→pub struct InterpolationContext {
134→    /// Prompt values from current run
135→    pub prompts: HashMap<String, String>,
136→
137→    /// Saved preferences from previous runs
138→    pub preferences: HashMap<String, String>,
139→
140→    /// User-defined variables from `vars:` config
141→    pub vars: HashMap<String, String>,
142→
143→    /// Environment variables
144→    pub env: HashMap<String, String>,
145→
146→    /// Built-in variables (project_name, project_root, bivvy_version)
147→    pub builtins: HashMap<String, String>,
148→}
