150→impl InterpolationContext {
151→    /// Create a new context with built-in variables.
152→    pub fn new() -> Self {
153→        let mut builtins = HashMap::new();
154→        builtins.insert(
155→            "bivvy_version".to_string(),
156→            env!("CARGO_PKG_VERSION").to_string(),
157→        );
158→
159→        Self {
160→            builtins,
161→            ..Default::default()
162→        }
