186→    /// Resolve a variable name to its value.
187→    ///
188→    /// Resolution order: prompts > preferences > vars > env > builtins
189→    pub fn resolve(&self, name: &str) -> Option<String> {
190→        self.prompts
191→            .get(name)
192→            .or_else(|| self.preferences.get(name))
193→            .or_else(|| self.vars.get(name))
194→            .or_else(|| self.env.get(name))
195→            .or_else(|| self.builtins.get(name))
196→            .cloned()
197→    }
198→}
