200→/// Resolve all variables in an interpolated string.
201→///
202→/// # Errors
203→///
204→/// Returns `ConfigValidationError` if any variable is not found in the context.
205→pub fn resolve_string(input: &str, context: &InterpolationContext) -> Result<String> {
206→    let segments = parse_interpolation(input);
207→    let mut result = String::new();
208→
209→    for segment in segments {
210→        match segment {
211→            Segment::Literal(text) => result.push_str(&text),
212→            Segment::Variable(name) => {
213→                let value =
214→                    context
215→                        .resolve(&name)
216→                        .ok_or_else(|| BivvyError::ConfigValidationError {
217→                            message: format!("Unresolved variable: ${{{}}}", name),
218→                        })?;
219→                result.push_str(&value);
220→            }
221→        }
222→    }
223→
224→    Ok(result)
225→}
226→
227→/// Resolve string with optional default value for missing variables.
228→///
229→/// Unlike `resolve_string`, this never fails - missing variables
230→/// are replaced with the provided default.
231→pub fn resolve_string_with_default(
232→    input: &str,
233→    context: &InterpolationContext,
234→    default: &str,
235→) -> String {
236→    let segments = parse_interpolation(input);
237→    let mut result = String::new();
238→
239→    for segment in segments {
240→        match segment {
241→            Segment::Literal(text) => result.push_str(&text),
242→            Segment::Variable(name) => {
243→                let value = context
244→                    .resolve(&name)
245→                    .unwrap_or_else(|| default.to_string());
246→                result.push_str(&value);
247→            }
248→        }
249→    }
250→
251→    result
252→}
